def _check_dependents(gpx_object: Any, fieldname: str) ->Tuple[str, str]:
    fields = gpx_object.gpx_10_fields + gpx_object.gpx_11_fields
    for field in fields:
        if isinstance(field, str) and ':' in field:
            parts = field.partition(':')
            if parts[2] == fieldname:
                return (parts[0], fieldname)
    return ('', '')

