    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if instance is None:
        return ''
    if not prettyprint:
        indent = ''

    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = instance.gpx_11_fields

    body = []
    attributes = []

    current_indent = indent
    indent_stack = [indent]
    tag_stack = []

    for gpx_field in fields:
        if isinstance(gpx_field, str):
            gpx_field_tag = gpx_field.partition(':')[0]
            if gpx_field_tag.startswith('/'):
                if tag_stack:
                    closed_tag = tag_stack.pop()
                    indent_stack.pop()
                    current_indent = indent_stack[-1]
                    body.append(f'\n{current_indent}</{closed_tag}>')
            else:
                tag_stack.append(gpx_field_tag)
                current_indent = indent_stack[-1] + '  '
                indent_stack.append(current_indent)
                body.append(f'\n{indent_stack[-2]}<{gpx_field_tag}>')
        else:
            value = getattr(instance, gpx_field.name)
            if gpx_field.attribute:
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=indent)
                if xml_value:
                    attributes.append(xml_value)
            else:
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=f'{current_indent}  ')
                if xml_value:
                    body.append(xml_value)

    if tag is None:
        return ''.join(body)

    for key, val in custom_attributes.items():
