    attr_str = (' ' + ' '.join(attributes)) if attributes else ''
    body_str = ''.join(body)

    if not body_str and not empty_body:
        return f'\n{indent}<{tag}{attr_str} />'
    else:
        if prettyprint:
            return f'\n{indent}<{tag}{attr_str}>{body_str}\n{indent}</{tag}>'
        else:
            return f'\n{indent}<{tag}{attr_str}>{body_str}</{tag}>'

def to_xml(self, value: Any, version: str, nsmap: Any=None, prettyprint:
